using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

namespace HearthStoner
{
    public sealed class Entity
    {
        public int Id;
        public string CardId = "";
        public readonly Dictionary<string, string> Tags = new Dictionary<string, string>();

        /// <summary>Game turn (GameEntity TURN) when the entity entered its current zone.</summary>
        public int ZoneTurn;
        /// <summary>Part of the starting 30 (or 40) cards, as opposed to generated by a card effect.</summary>
        public bool StartedInDeck;
        /// <summary>Who controlled it when the game was set up, i.e. whose deck it came from. Survives Mind Control
        /// and other steal effects, which change CONTROLLER.</summary>
        public int StartController;
        /// <summary>Created straight into a hand while the game was being set up. Every real card starts in the
        /// deck, so this is the Coin, even while it's hidden in the opponent's hand.</summary>
        public bool SetupCoin;
        /// <summary>Was in the opening hand and stayed there through the mulligan.</summary>
        public bool KeptInMulligan;
        /// <summary>Drawn to replace a card thrown back in the mulligan.</summary>
        public bool MulliganReplacement;
        /// <summary>Turn its owner played it from hand (PLAY block), or -1.</summary>
        public int PlayedTurn = -1;
        /// <summary>Card id it had when it was last seen in play, kept even if hidden again (e.g. bounced to hand).</summary>
        public string LastKnownCardId = "";
        /// <summary>The first card id this entity was revealed as. Some cards change form (e.g. Flight Maneuvers
        /// flips between two versions, even in your deck or hand), so this is what matches your deck list.</summary>
        public string FirstCardId = "";
        /// <summary>Returned to its owner's hand from play, so its identity is public.</summary>
        public bool ReturnedToHand;

        public string Zone => Tag("ZONE");
        public string CardType => Tag("CARDTYPE");
        public int Controller => Int("CONTROLLER");
        public string Tag(string t) => Tags.TryGetValue(t, out var v) ? v : null;
        public int Int(string t) => Tags.TryGetValue(t, out var v) && int.TryParse(v, out var n) ? n : 0;
        public bool Flag(string t) => Int(t) != 0;

        public int Attack => Int("ATK");
        public int Health => Int("HEALTH") - Int("DAMAGE");
        public int Armor => Int("ARMOR");
        public bool IsMinion => CardType == "MINION";
        public string KnownCardId => !string.IsNullOrEmpty(CardId) ? CardId : LastKnownCardId;
    }

    public enum GameEventKind { GameStart, Turn, Draw, Play, Died, Revealed, GameEnd, Info, Secret }

    public sealed class GameEvent
    {
        public GameEventKind Kind;
        public bool Friendly;          // true = you, false = opponent
        public string CardId;
        public string Text;
    }

    /// <summary>What we know about one of the opponent's hidden secrets.</summary>
    /// <summary>A choice the game offered (mulligan, Discover, Choose One...) and what was picked.</summary>
    public sealed class Choice
    {
        public int Id;
        public int PlayerId;
        public string Type;            // MULLIGAN, GENERAL, ...
        public int SourceEntity;
        public string SourceCardId;
        public int Turn;
        public List<int> Entities = new List<int>();
        public List<string> CardIds = new List<string>();
        public List<int> Chosen = new List<int>();
        public bool Resolved;
    }

    public sealed class SecretState
    {
        public int EntityId;
        public int PlayedTurn;
        /// <summary>Secrets it can still be. Starts as every Standard secret of their class.</summary>
        public readonly HashSet<string> Candidates = new HashSet<string>();
        /// <summary>Created by another card (Discover etc.): could be outside the usual pool.</summary>
        public string CreatedBy;
    }

    /// <summary>
    /// Rebuilds the game from Power.log's GameState.DebugPrintPower() lines: every entity with its tags, both
    /// players, turn/step, plus derived knowledge (what's in each hand and where it came from, which cards started in
    /// the deck, what secrets the opponent can have). Only uses information the log gives your client, i.e. what you
    /// are allowed to see.
    /// </summary>
    public sealed class GameTracker
    {
        /// <summary>Lock held while lines are applied; take it to read state from another thread.</summary>
        public readonly object Sync = new object();

        private static readonly Regex PowerLine = new Regex(@"GameState\.DebugPrintPower\(\) -\s*(.*)$");
        private static readonly Regex GameLine = new Regex(@"GameState\.DebugPrintGame\(\) - PlayerID=(\d+), PlayerName=(.+)$");

        private static readonly Regex FullEntity = new Regex(@"^FULL_ENTITY - (?:Creating|Updating) (?:ID=(\d+)|(\[.*?\])) CardID=(\S*)");
        private static readonly Regex ShowEntity = new Regex(@"^SHOW_ENTITY - Updating Entity=(.+?) CardID=(\S+)");
        private static readonly Regex ChangeEntity = new Regex(@"^CHANGE_ENTITY - Updating Entity=(.+?) CardID=(\S+)");
        private static readonly Regex HideEntity = new Regex(@"^HIDE_ENTITY - Entity=(.+?) tag=(\w+) value=(\S+)");
        private static readonly Regex TagChange = new Regex(@"^TAG_CHANGE Entity=(.+?) tag=(\w+) value=(\S+)");
        private static readonly Regex BlockTag = new Regex(@"^tag=(\w+) value=(\S+)");
        private static readonly Regex PlayerEnt = new Regex(@"^Player EntityID=(\d+) PlayerID=(\d+)");
        private static readonly Regex GameEnt = new Regex(@"^GameEntity EntityID=(\d+)");
        private static readonly Regex BlockStart = new Regex(@"^BLOCK_START BlockType=(\w+) Entity=(.+?) EffectCardId=.*?(?: Target=(.+?)(?: SubOption=|$)|$)");
        private static readonly Regex BracketId = new Regex(@"\bid=(\d+)");

        private readonly CardDb _cards;
        private readonly Action<GameEvent> _emit;

        public Dictionary<int, Entity> Entities { get; } = new Dictionary<int, Entity>();
        public Dictionary<int, string> PlayerNames { get; } = new Dictionary<int, string>();      // PlayerID -> name
        private readonly Dictionary<int, int> _playerEntityToPlayerId = new Dictionary<int, int>();
        private readonly Dictionary<int, int> _playerIdToEntity = new Dictionary<int, int>();
        private readonly Dictionary<string, int> _nameToPlayerId = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        public int FriendlyPlayerId { get; private set; }
        public int OpponentPlayerId => FriendlyPlayerId == 0 ? 0 : 3 - FriendlyPlayerId;
        public int Turn { get; private set; }
        public string Step { get; private set; } = "";
        public int CurrentPlayerId { get; private set; }
        public bool InGame { get; private set; }
        /// <summary>True from game creation until the first MAIN_READY step (deck creation + mulligan).</summary>
        public bool InSetup { get; private set; }
        public bool InMulligan => InGame && (Step == "BEGIN_MULLIGAN" || (InSetup && Step == ""));
        public bool IsFriendlyTurn => CurrentPlayerId != 0 && CurrentPlayerId == FriendlyPlayerId;
        public bool Quiet { get; set; }     // suppress events while replaying old log content
        public string Result { get; private set; }

        /// <summary>If set (your BattleTag from memory), used to identify which player is you.</summary>
        public string FriendlyNameHint { get; set; }

        /// <summary>Your deck list for this game (card ids, from memory), if known.</summary>
        public List<string> FriendlyDeckList { get; set; }
        public string FriendlyDeckName { get; set; }

        public List<string> FriendlyPlayed => FriendlyPlayLog.Select(p => p.CardId).ToList();
        public List<string> OpponentPlayed => OpponentPlayLog.Select(p => p.CardId).ToList();
        public List<string> FriendlyDrawn { get; } = new List<string>();
        /// <summary>Your most recent draw (for the overlay's highlight).</summary>
        public (string CardId, DateTime At) LastFriendlyDraw { get; private set; }

        public Dictionary<int, SecretState> OpponentSecrets { get; } = new Dictionary<int, SecretState>();
        /// <summary>Secrets the opponent has revealed this game (card ids).</summary>
        public List<string> RevealedSecrets { get; } = new List<string>();

        public int FriendlyCardsPlayedThisTurn { get; private set; }

        /// <summary>How each opponent turn went: mana they had, mana left unused, cards in hand at the end, cards played.</summary>
        public sealed class OpponentTurn
        {
            public int Turn;
            /// <summary>Mana crystals (max 10).</summary>
            public int Crystals;
            /// <summary>Mana they could spend: crystals plus temporary mana (Coin, Innervate...) minus overload.</summary>
            public int Mana;
            public int Unspent;
            public int HandAtEnd;
            public int CardsPlayed;
            public List<int> CostsPlayed = new List<int>();
        }
        public List<OpponentTurn> OpponentTurns { get; } = new List<OpponentTurn>();
        private OpponentTurn _oppTurn;

        // Counters for cards that scale ("for each spell you've cast this game" etc.).
        public int FriendlySpellsCast { get; private set; }
        public int FriendlyMinionsDied { get; private set; }
        public int FriendlyMinionsDiedThisTurn { get; private set; }
        public int FriendlyHeroPowerUses { get; private set; }
        public int FriendlyCardsDrawn { get; private set; }
        public int OpponentSpellsCast { get; private set; }

        /// <summary>Hearthstone client build (from the log header); used to spot patches.</summary>
        public string BuildNumber { get; private set; }
        /// <summary>This game's mode and format as the log names them ("GT_RANKED", "FT_STANDARD"); null until printed.</summary>
        public string GameType { get; private set; }
        public string FormatType { get; private set; }

        /// <summary>Raised (inside the lock) whenever state changes in a way the advice depends on.</summary>
        public event Action Changed;

        private Entity _current;       // entity whose indented "tag=X value=Y" lines we're reading
        private Entity _pendingShow;   // last SHOW_ENTITY, to detect "this card is in my hand" (friendly player)

        // Blocks and pending secret checks.
        private sealed class Block { public string Type; public int Source; public int Target; }
        private readonly List<Block> _blocks = new List<Block>();
        private sealed class SecretCheck
        {
            public HashSet<SecretTrigger> Triggers = new HashSet<SecretTrigger>();
            public List<int> Secrets = new List<int>();
            public bool TheyHadBoardSpace;
            public bool RevealedDuring;
            public bool CheckYouHaveMinionAtResolve;
            public bool YouHadMinion;
        }
        private readonly List<SecretCheck> _pendingChecks = new List<SecretCheck>();

        private static readonly Regex ChoicesHead = new Regex(@"GameState\.DebugPrintEntityChoices\(\) - id=(\d+) Player=(.+?) TaskList=\S* ChoiceType=(\w+)");
        private static readonly Regex ChoicesSource = new Regex(@"GameState\.DebugPrintEntityChoices\(\) -\s+Source=(.+?)\s*$");
        private static readonly Regex ChoicesEntity = new Regex(@"GameState\.DebugPrintEntityChoices\(\) -\s+Entities\[\d+\]=(.+?)\s*$");
        private static readonly Regex ChosenHead = new Regex(@"GameState\.DebugPrintEntitiesChosen\(\) - id=(\d+) Player=(.+?) EntitiesCount=(\d+)");
        private static readonly Regex ChosenEntity = new Regex(@"GameState\.DebugPrintEntitiesChosen\(\) -\s+Entities\[\d+\]=(.+?)\s*$");
        private static readonly Regex OptionsHead = new Regex(@"GameState\.DebugPrintOptions\(\) - id=(\d+)");
        private static readonly Regex OptionLine = new Regex(@"GameState\.DebugPrintOptions\(\) -\s+option \d+ type=(\w+) mainEntity=(.*?) error=(\w+)");
        private static readonly Regex BracketCardId = new Regex(@"\bcardId=(\S*)");
        private static readonly Regex BracketPlayer = new Regex(@"\bplayer=(\d+)");

        /// <summary>All choices this game, oldest first.</summary>
        public List<Choice> Choices { get; } = new List<Choice>();
        private Choice _readingChoice;
        private Choice _readingChosen;
        /// <summary>Your open choice (Discover etc.), or null.</summary>
        public Choice OpenFriendlyChoice => Choices.LastOrDefault(c => !c.Resolved && c.PlayerId == FriendlyPlayerId && c.Type != "MULLIGAN");

        /// <summary>Your cards the game says you can play right now (from the latest options list).</summary>
        public HashSet<int> Playable { get; } = new HashSet<int>();
        /// <summary>Entities you can use right now: hand cards, hero power, locations, attackers.</summary>
        public HashSet<int> UsableNow { get; } = new HashSet<int>();
        private bool _optionsFresh;

        // Plays are stored by entity and looked up when read: an opponent's card is only revealed just after
        // its PLAY block starts, so its card id isn't known yet at that moment.
        private readonly List<(int Turn, int Entity, bool Created)> _opponentPlays = new List<(int, int, bool)>();
        private readonly List<(int Turn, int Entity)> _friendlyPlays = new List<(int, int)>();
        /// <summary>Cards the opponent played this game in order (turn, card id; "" if never revealed).</summary>
        public List<(int Turn, string CardId, bool Created)> OpponentPlayLog =>
            _opponentPlays.Select(p => (p.Turn, EntityCardId(p.Entity) ?? "", p.Created)).ToList();
        /// <summary>Cards you played this game in order (turn, card id).</summary>
        public List<(int Turn, string CardId)> FriendlyPlayLog =>
            _friendlyPlays.Select(p => (p.Turn, EntityCardId(p.Entity) ?? "")).ToList();

        public GameTracker(CardDb cards, Action<GameEvent> emit)
        {
            _cards = cards;
            _emit = emit;
        }

        // ================================================================== queries used by the advisor

        public Entity PlayerEntity(int playerId) =>
            _playerIdToEntity.TryGetValue(playerId, out var eid) && Entities.TryGetValue(eid, out var e) ? e : null;

        public Entity Hero(int playerId)
        {
            var p = PlayerEntity(playerId);
            var heroId = p?.Int("HERO_ENTITY") ?? 0;
            if (heroId != 0 && Entities.TryGetValue(heroId, out var h)) return h;
            return Entities.Values.FirstOrDefault(x => x.CardType == "HERO" && x.Zone == "PLAY" && x.Controller == playerId);
        }

        public string HeroClass(int playerId)
        {
            var hero = Hero(playerId);
            var info = _cards.ById(hero?.CardId);
            return info?.CardClass;
        }

        public IEnumerable<Entity> Zone(int playerId, string zone) =>
            Entities.Values.Where(e => e.Controller == playerId && e.Zone == zone && IsCardEntity(e));

        public List<Entity> Minions(int playerId) =>
            Zone(playerId, "PLAY").Where(e => e.IsMinion).OrderBy(e => e.Int("ZONE_POSITION")).ToList();

        public List<Entity> Hand(int playerId) =>
            Zone(playerId, "HAND").OrderBy(e => e.Int("ZONE_POSITION")).ToList();

        public int DeckCount(int playerId) => Zone(playerId, "DECK").Count();

        public Entity Weapon(int playerId) => Zone(playerId, "PLAY").FirstOrDefault(e => e.CardType == "WEAPON");

        /// <summary>Mana available right now (this turn's crystals, minus used and locked, plus temporary).</summary>
        public int AvailableMana(int playerId)
        {
            var p = PlayerEntity(playerId);
            if (p == null) return 0;
            return Math.Max(0, p.Int("RESOURCES") + p.Int("TEMP_RESOURCES") - p.Int("RESOURCES_USED") - p.Int("OVERLOAD_LOCKED"));
        }

        /// <summary>The player's mana crystal cap: 10, unless a card raised it (MAXRESOURCES, e.g. some Druid cards).</summary>
        public int MaxMana(int playerId)
        {
            var m = PlayerEntity(playerId)?.Int("MAXRESOURCES") ?? 0;
            return m > 0 ? m : 10;
        }

        /// <summary>Mana crystals the player will have next turn (up to their cap), minus overload owed.</summary>
        public int NextTurnMana(int playerId)
        {
            var p = PlayerEntity(playerId);
            if (p == null) return 0;
            return Math.Max(0, Math.Min(MaxMana(playerId), p.Int("RESOURCES") + 1) - p.Int("OVERLOAD_OWED"));
        }

        /// <summary>Card ids the opponent revealed that were part of their starting deck (useful for archetype guessing).</summary>
        public List<string> OpponentOriginalCardsSeen() =>
            Entities.Values
                .Where(e => e.StartedInDeck && e.StartController == OpponentPlayerId && !string.IsNullOrEmpty(e.KnownCardId) && IsCardEntity(e)
                            && !_cards.IsCoin(e.KnownCardId))
                .Select(e => e.KnownCardId)
                .ToList();

        /// <summary>Your deck's remaining known cards (deck list minus cards that have left your deck), with counts.</summary>
        public Dictionary<string, int> FriendlyRemainingDeck()
        {
            var result = new Dictionary<string, int>();
            if (FriendlyDeckList == null) return result;
            foreach (var id in FriendlyDeckList) result[id] = (result.TryGetValue(id, out var n) ? n : 0) + 1;

            foreach (var e in Entities.Values)
            {
                if (!IsCardEntity(e)) continue;
                // Cards from your starting deck count as gone once they leave it, even if the opponent stole them.
                var mine = e.StartedInDeck ? e.StartController == FriendlyPlayerId : e.Controller == FriendlyPlayerId;
                if (!mine) continue;
                var id = e.KnownCardId;
                if (string.IsNullOrEmpty(id)) continue;
                if (e.StartedInDeck && (e.Zone != "DECK" || e.Controller != FriendlyPlayerId))
                {
                    // Match the deck list by the card it is now, the card it first was, or the base card of a
                    // changed form (CATA_479t -> CATA_479).
                    var match = new[] { id, e.FirstCardId, BaseCardId(id), BaseCardId(e.FirstCardId) }
                        .FirstOrDefault(c => !string.IsNullOrEmpty(c) && result.TryGetValue(c, out var left) && left > 0);
                    if (match != null) result[match]--;
                }
                else if (!e.StartedInDeck && e.Zone == "DECK")
                {
                    // Shuffled into your deck by an effect and visible to you.
                    result[id] = (result.TryGetValue(id, out var n) ? n : 0) + 1;
                }
            }
            foreach (var k in result.Where(kv => kv.Value <= 0).Select(kv => kv.Key).ToList()) result.Remove(k);
            return result;
        }

        /// <summary>"CATA_479t" / "CATA_479t3" -> "CATA_479": the card a token form or alternate version belongs to.</summary>
        public static string BaseCardId(string id) =>
            string.IsNullOrEmpty(id) ? null : Regex.Replace(id, @"t\d*$", "");

        public string CardName(Entity e) => string.IsNullOrEmpty(e?.KnownCardId) ? "an unknown card" : _cards.NameOf(e.KnownCardId);

        /// <summary>Card id of an entity if known, else null (never an empty string).</summary>
        public string EntityCardId(int entityId) =>
            Entities.TryGetValue(entityId, out var e) && !string.IsNullOrEmpty(e.KnownCardId) ? e.KnownCardId : null;

        private static bool IsCardEntity(Entity e)
        {
            var t = e.CardType;
            return t != "PLAYER" && t != "GAME" && t != "ENCHANTMENT" && t != "HERO_POWER" && t != "HERO" || (t == "HERO" && e.Zone != "PLAY" && e.Zone != "SETASIDE" && e.Zone != "REMOVEDFROMGAME" && e.Zone != "GRAVEYARD");
        }

        // ================================================================== log parsing

        /// <summary>Time of day of the last line fed (from its "D 01:20:22.82..." prefix).</summary>
        public TimeSpan LastLineTime { get; private set; }

        public void Feed(string line)
        {
            if (line.Length > 18 && line[0] == 'D' && line[1] == ' ' && TimeSpan.TryParse(line.Substring(2, 8), out var lt)) LastLineTime = lt;
            if (line.Contains("DebugPrintGame() - BuildNumber="))
            {
                var i = line.IndexOf("BuildNumber=", StringComparison.Ordinal);
                BuildNumber = line.Substring(i + 12).Trim();
                return;
            }
            // The mode and format, printed right after CREATE_GAME (see GameModes).
            if (line.Contains("DebugPrintGame() - GameType=")) { GameType = line.Substring(line.IndexOf("GameType=", StringComparison.Ordinal) + 9).Trim(); return; }
            if (line.Contains("DebugPrintGame() - FormatType=")) { FormatType = line.Substring(line.IndexOf("FormatType=", StringComparison.Ordinal) + 11).Trim(); return; }
            var g = GameLine.Match(line);
            if (g.Success)
            {
                var pid = int.Parse(g.Groups[1].Value);
                var name = g.Groups[2].Value.Trim();
                PlayerNames[pid] = name;
                if (!IsPlaceholderName(name)) _nameToPlayerId[name] = pid;
                TryIdentifyFriendlyByName();
                return;
            }

            if (line.Contains("GameState.DebugPrintEntityChoices") || line.Contains("GameState.DebugPrintEntitiesChosen") ||
                line.Contains("GameState.DebugPrintOptions"))
            {
                FeedChoiceOrOption(line);
                return;
            }

            var m = PowerLine.Match(line);
            if (!m.Success) return;
            var p = m.Groups[1].Value.Trim();
            if (p.Length == 0) return;

            if (!BlockTag.IsMatch(p)) FlushShow();

            if (p == "CREATE_GAME") { StartGame(); return; }

            Match x;
            if ((x = BlockTag.Match(p)).Success)
            {
                // A brand-new entity's tags are its starting values; tags under SHOW_ENTITY/CHANGE_ENTITY are real changes.
                if (_current != null) SetTag(_current, x.Groups[1].Value, x.Groups[2].Value, initial: ReferenceEquals(_current, _newEntity));
                return;
            }
            if ((x = GameEnt.Match(p)).Success) { _gameEntityId = int.Parse(x.Groups[1].Value); _current = GetOrCreate(_gameEntityId); _newEntity = _current; return; }
            if ((x = PlayerEnt.Match(p)).Success)
            {
                var eid = int.Parse(x.Groups[1].Value);
                var pid = int.Parse(x.Groups[2].Value);
                _playerEntityToPlayerId[eid] = pid;
                _playerIdToEntity[pid] = eid;
                _current = GetOrCreate(eid);
                _newEntity = _current;
                return;
            }
            if ((x = FullEntity.Match(p)).Success)
            {
                var id = x.Groups[1].Success ? int.Parse(x.Groups[1].Value) : ResolveId(x.Groups[2].Value);
                var isNew = !Entities.ContainsKey(id);
                _current = GetOrCreate(id);
                if (x.Groups[3].Value.Length > 0) SetCardId(_current, x.Groups[3].Value);
                if (isNew) _newEntity = _current;
                return;
            }
            if ((x = ShowEntity.Match(p)).Success)
            {
                _current = GetOrCreate(ResolveId(x.Groups[1].Value));
                SetCardId(_current, x.Groups[2].Value);
                _pendingShow = _current;
                return;
            }
            if ((x = ChangeEntity.Match(p)).Success)
            {
                _current = GetOrCreate(ResolveId(x.Groups[1].Value));
                SetCardId(_current, x.Groups[2].Value);
                return;
            }
            if ((x = HideEntity.Match(p)).Success)
            {
                var e = GetOrCreate(ResolveId(x.Groups[1].Value));
                SetTag(e, x.Groups[2].Value, x.Groups[3].Value, initial: false);
                _current = null;
                return;
            }

            FinishNewEntity();

            if ((x = TagChange.Match(p)).Success)
            {
                _current = null;
                HandleTagChange(x.Groups[1].Value, x.Groups[2].Value, x.Groups[3].Value);
                return;
            }
            if ((x = BlockStart.Match(p)).Success)
            {
                _current = null;
                var target = x.Groups[3].Success ? ResolveId(x.Groups[3].Value) : 0;
                OnBlockStart(x.Groups[1].Value, ResolveId(x.Groups[2].Value), target);
                return;
            }
            if (p.StartsWith("BLOCK_END"))
            {
                _current = null;
                if (_blocks.Count > 0) _blocks.RemoveAt(_blocks.Count - 1);
                return;
            }
            _current = null;
        }

        // A FULL_ENTITY's tags arrive on the following lines; once they're done we know its zone/controller/creator.
        private Entity _newEntity;
        private void FinishNewEntity()
        {
            var e = _newEntity;
            _newEntity = null;
            if (e == null || !InGame) return;
            e.ZoneTurn = Turn;
            var zone = e.Zone;
            var created = e.Int("CREATOR") != 0 || e.Int("CREATOR_DBID") != 0;
            if (InSetup && zone == "HAND" && IsCardEntity(e) && (_cards.IsCoin(e.CardId) || string.IsNullOrEmpty(e.CardId) || created))
                e.SetupCoin = true;
            else if (InSetup && !created && (zone == "DECK" || zone == "HAND") && IsCardEntity(e) && !_cards.IsCoin(e.CardId))
            {
                e.StartedInDeck = true;
                e.StartController = e.Controller;
            }
            if (zone == "SECRET" && e.Controller == OpponentPlayerId && e.Flag("SECRET")) AddOpponentSecret(e);
            // The client is only told card ids for its own hand at game start.
            if (FriendlyPlayerId == 0 && InSetup && zone == "HAND" && !string.IsNullOrEmpty(e.CardId) && e.Controller != 0 && !created && !_cards.IsCoin(e.CardId))
                SetFriendly(e.Controller);
        }

        private void FlushShow()
        {
            FinishNewEntity();
            if (_pendingShow == null) return;
            var e = _pendingShow;
            _pendingShow = null;
            if (FriendlyPlayerId == 0 && e.Zone == "HAND" && e.CardType != "ENCHANTMENT" && e.Controller != 0)
                SetFriendly(e.Controller);
        }

        private void SetFriendly(int playerId)
        {
            if (FriendlyPlayerId != 0) return;
            FriendlyPlayerId = playerId;
            Emit(GameEventKind.Info, true, null, $"You are player {FriendlyPlayerId} ({NameOf(FriendlyPlayerId)})");
        }

        private void StartGame()
        {
            Entities.Clear();
            PlayerNames.Clear();
            _playerEntityToPlayerId.Clear();
            _playerIdToEntity.Clear();
            _nameToPlayerId.Clear();
            UnresolvedNameLookups = 0;
            UnresolvedNames.Clear();

            FriendlyDrawn.Clear();
            OpponentSecrets.Clear();
            RevealedSecrets.Clear();
            Choices.Clear();
            Playable.Clear();
            UsableNow.Clear();
            _opponentPlays.Clear();
            _friendlyPlays.Clear();
            OpponentTurns.Clear();
            _oppTurn = null;
            FriendlySpellsCast = FriendlyMinionsDied = FriendlyMinionsDiedThisTurn = FriendlyHeroPowerUses = FriendlyCardsDrawn = OpponentSpellsCast = 0;
            _readingChoice = null;
            _readingChosen = null;
            _blocks.Clear();
            _pendingChecks.Clear();
            FriendlyPlayerId = 0;
            CurrentPlayerId = 0;
            FriendlyCardsPlayedThisTurn = 0;
            Turn = 0;
            Step = "";
            Result = null;
            InGame = true;
            InSetup = true;
            FriendlyDeckList = null;
            FriendlyDeckName = null;
            _current = null;
            _pendingShow = null;
            _newEntity = null;
            _gameEntityId = 0;
            GameType = null;
            FormatType = null;
            Emit(GameEventKind.GameStart, true, null, "Game started");
        }

        private void TryIdentifyFriendlyByName()
        {
            if (FriendlyPlayerId != 0 || string.IsNullOrEmpty(FriendlyNameHint)) return;
            var hint = FriendlyNameHint.Split('#')[0];
            foreach (var kv in PlayerNames)
                if (kv.Value.Split('#')[0].Equals(hint, StringComparison.OrdinalIgnoreCase))
                    SetFriendly(kv.Key);
        }

        /// <summary>A player's name without the BattleTag number ("Musume#1455" -> "Musume"), or null while it's
        /// still hidden (the opponent shows as "UNKNOWN HUMAN PLAYER" until the game reveals them).</summary>
        public string DisplayName(int playerId) =>
            PlayerNames.TryGetValue(playerId, out var n) && !IsPlaceholderName(n) ? n.Split('#')[0] : null;

        private static bool IsPlaceholderName(string name) =>
            string.IsNullOrEmpty(name) || name.StartsWith("UNKNOWN", StringComparison.OrdinalIgnoreCase);

        /// <summary>Player entities are referred to by name ("Musume#1455") in TAG_CHANGE lines.</summary>
        private int ResolvePlayerByName(string name)
        {
            if (_nameToPlayerId.TryGetValue(name, out var pid)) return pid;
            var guess = GuessPlayerIdForName(name);
            if (!string.IsNullOrEmpty(FriendlyNameHint) && name.Split('#')[0].Equals(FriendlyNameHint.Split('#')[0], StringComparison.OrdinalIgnoreCase))
            {
                if (FriendlyPlayerId == 0 && guess != 0) SetFriendly(guess);
                if (FriendlyPlayerId != 0) { _nameToPlayerId[name] = FriendlyPlayerId; return FriendlyPlayerId; }
            }
            if (guess != 0) _nameToPlayerId[name] = guess;
            return guess;
        }

        /// <summary>Names that couldn't be matched to a player (for the self-test).</summary>
        public int UnresolvedNameLookups { get; private set; }
        /// <summary>A few of those names, to say which ones in the self-test.</summary>
        public List<string> UnresolvedNames { get; } = new List<string>();

        private int GuessPlayerIdForName(string name)
        {
            // Exact match with the names from DebugPrintGame.
            foreach (var kv in PlayerNames)
                if (string.Equals(kv.Value, name, StringComparison.OrdinalIgnoreCase)) return kv.Key;

            // The one player we only know by a placeholder ("UNKNOWN HUMAN PLAYER") or not at all. The opponent is
            // logged under a placeholder until their name is revealed, then under their real BattleTag.
            var real = new HashSet<int>(_nameToPlayerId.Where(kv => !IsPlaceholderName(kv.Key)).Select(kv => kv.Value));
            var unnamed = _playerIdToEntity.Keys.Where(id => !real.Contains(id)).ToList();
            if (unnamed.Count == 1)
            {
                if (!IsPlaceholderName(name)) PlayerNames[unnamed[0]] = name;
                return unnamed[0];
            }
            // Not you: then it's the opponent. (Against the AI the opponent is listed as "The Innkeeper" but logged
            // under its hero's name, e.g. "Mal'Ganis".)
            var you = !string.IsNullOrEmpty(FriendlyNameHint) ? FriendlyNameHint : PlayerNames.TryGetValue(FriendlyPlayerId, out var yn) ? yn : null;
            if (FriendlyPlayerId != 0 && OpponentPlayerId != 0 && !IsPlaceholderName(name) && !string.IsNullOrEmpty(you) &&
                !name.Split('#')[0].Equals(you.Split('#')[0], StringComparison.OrdinalIgnoreCase))
                return OpponentPlayerId;
            UnresolvedNameLookups++;
            if (UnresolvedNames.Count < 3 && !UnresolvedNames.Contains(name)) UnresolvedNames.Add(name);
            return 0;
        }

        private int _gameEntityId;

        private void HandleTagChange(string entityRef, string tag, string value)
        {
            // The game entity is written both as "GameEntity" and by its id ("Entity=1").
            if (entityRef == "GameEntity" || (_gameEntityId != 0 && entityRef.Trim() == _gameEntityId.ToString()))
            {
                if (_gameEntityId != 0) GetOrCreate(_gameEntityId).Tags[tag] = value;
                if (tag == "TURN" && int.TryParse(value, out var t))
                {
                    ResolvePendingChecks();
                    CloseOpponentTurn();
                    FriendlyMinionsDiedThisTurn = 0;
                    Turn = t;
                    FriendlyCardsPlayedThisTurn = 0;
                    Playable.Clear();
                    UsableNow.Clear();
                    if (FriendlyPlayerId != 0 && !IsFriendlyTurnNumber(t)) _oppTurn = new OpponentTurn { Turn = t };
                    Emit(GameEventKind.Turn, true, null, $"--- Turn {(t + 1) / 2} ({(t % 2 == 1 ? "first" : "second")} player) ---");
                }
                else if (tag == "STEP")
                {
                    var prev = Step;
                    Step = value;
                    if (value == "MAIN_READY" && InSetup) EndSetup();
                    if (value == "MAIN_END" && IsFriendlyTurn) QueueYourTurnEnds();
                    if (value != prev && (value == "MAIN_START" || value == "MAIN_READY")) ResolvePendingChecks();
                    if (value == "FINAL_GAMEOVER" && InGame)
                    {
                        ResolvePendingChecks();
                        CloseOpponentTurn();
                        InGame = false;
                        Emit(GameEventKind.GameEnd, true, null, "Game over");
                    }
                }
                Changed?.Invoke();
                return;
            }

            var id = ResolveId(entityRef);
            if (id == 0)
            {
                var pid = ResolvePlayerByName(entityRef);
                if (pid == 0 || !_playerIdToEntity.TryGetValue(pid, out id)) return;
            }

            var e = GetOrCreate(id);
            if (_playerEntityToPlayerId.TryGetValue(id, out var playerId))
            {
                if (tag == "CURRENT_PLAYER" && value == "1") CurrentPlayerId = playerId;
                if (tag == "PLAYSTATE" && (value == "WON" || value == "LOST" || value == "TIED") && playerId == FriendlyPlayerId)
                {
                    Result = value;
                    Emit(GameEventKind.Info, true, null, $"Result: you {value.ToLower()}");
                }
            }
            SetTag(e, tag, value, initial: false);
            Changed?.Invoke();
        }

        private void EndSetup()
        {
            InSetup = false;
            // Opening-hand cards still in hand after the mulligan were kept.
            foreach (var e in Entities.Values)
                if (e.StartedInDeck && e.Zone == "HAND" && !e.MulliganReplacement) e.KeptInMulligan = true;
        }

        private void SetCardId(Entity e, string cardId)
        {
            if (string.IsNullOrEmpty(cardId)) return;
            var wasHidden = string.IsNullOrEmpty(e.CardId);
            e.CardId = cardId;
            e.LastKnownCardId = cardId;
            if (string.IsNullOrEmpty(e.FirstCardId)) e.FirstCardId = cardId;
            if (wasHidden && OpponentSecrets.ContainsKey(e.Id)) RevealSecret(e);
        }

        private void SetTag(Entity e, string tag, string value, bool initial)
        {
            var old = e.Tag(tag);
            e.Tags[tag] = value;
            if (initial || tag != "ZONE" || old == value) return;

            e.ZoneTurn = Turn;
            if (!InGame) return;
            OnZoneChange(e, old, value);
        }

        private void OnZoneChange(Entity e, string from, string to)
        {
            var friendly = FriendlyPlayerId != 0 && e.Controller == FriendlyPlayerId;
            var opponent = FriendlyPlayerId != 0 && e.Controller == OpponentPlayerId;

            if (from == "PLAY" && to == "HAND" && e.IsMinion) e.ReturnedToHand = true;
            if (to == "PLAY" && !string.IsNullOrEmpty(e.CardId)) e.LastKnownCardId = e.CardId;

            // Opponent's secret leaving the secret zone = it triggered (or was destroyed).
            if (from == "SECRET" && OpponentSecrets.ContainsKey(e.Id)) RevealSecret(e);
            if (to == "SECRET" && opponent && e.Flag("SECRET") && !OpponentSecrets.ContainsKey(e.Id)) AddOpponentSecret(e);

            if (from == "DECK" && to == "HAND")
            {
                if (InSetup && Step == "BEGIN_MULLIGAN") e.MulliganReplacement = true;
                if (friendly)
                {
                    FriendlyDrawn.Add(e.CardId);
                    FriendlyCardsDrawn++;
                    if (!Quiet) LastFriendlyDraw = (e.KnownCardId, DateTime.UtcNow);
                    Emit(GameEventKind.Draw, true, e.CardId, $"You drew {CardName(e)}");
                }
                else if (opponent)
                {
                    Emit(GameEventKind.Draw, false, null, "Opponent drew a card");
                }
            }
            else if (from == "PLAY" && to == "GRAVEYARD" && e.IsMinion)
            {
                if (friendly) { FriendlyMinionsDied++; FriendlyMinionsDiedThisTurn++; }
                Emit(GameEventKind.Died, friendly, e.KnownCardId, $"{(friendly ? "Your" : "Opponent's")} {CardName(e)} died");
                if (opponent && IsFriendlyTurn && e.PlayedTurn >= 0 && e.PlayedTurn == Turn - 1)
                    QueueCheck(new[] { SecretTrigger.TheirFreshMinionDies });
            }
        }

        /// <summary>Turn numbers alternate; the first player has the odd ones.</summary>
        public bool IsFriendlyTurnNumber(int turn)
        {
            var first = PlayerEntity(FriendlyPlayerId)?.Flag("FIRST_PLAYER") ?? false;
            return (turn % 2 == 1) == first;
        }

        private void CloseOpponentTurn()
        {
            if (_oppTurn == null) return;
            var p = PlayerEntity(OpponentPlayerId);
            if (p != null)
            {
                _oppTurn.Crystals = p.Int("RESOURCES");
                _oppTurn.Mana = p.Int("RESOURCES") + p.Int("TEMP_RESOURCES") - p.Int("OVERLOAD_LOCKED");
                _oppTurn.Unspent = AvailableMana(OpponentPlayerId);
            }
            _oppTurn.HandAtEnd = Hand(OpponentPlayerId).Count;
            OpponentTurns.Add(_oppTurn);
            _oppTurn = null;
        }

        // ================================================================== choices and options

        private void FeedChoiceOrOption(string line)
        {
            Match x;
            if ((x = ChoicesHead.Match(line)).Success)
            {
                var name = x.Groups[2].Value.Trim();
                _readingChoice = new Choice
                {
                    Id = int.Parse(x.Groups[1].Value),
                    PlayerId = ResolvePlayerByName(name),
                    Type = x.Groups[3].Value,
                    Turn = Turn,
                };
                Choices.Add(_readingChoice);
                _readingChosen = null;
                return;
            }
            if (_readingChoice != null && (x = ChoicesSource.Match(line)).Success)
            {
                var src = x.Groups[1].Value;
                _readingChoice.SourceEntity = src == "GameEntity" ? _gameEntityId : ResolveId(src);
                _readingChoice.SourceCardId = BracketCardId.Match(src) is var cm && cm.Success ? cm.Groups[1].Value : EntityCardId(_readingChoice.SourceEntity);
                return;
            }
            if (_readingChoice != null && (x = ChoicesEntity.Match(line)).Success)
            {
                var ent = x.Groups[1].Value;
                var id = ResolveId(ent);
                var cid = BracketCardId.Match(ent);
                _readingChoice.Entities.Add(id);
                _readingChoice.CardIds.Add(cid.Success && cid.Groups[1].Value.Length > 0 ? cid.Groups[1].Value : EntityCardId(id));
                // The mulligan choice tells us which player each name belongs to.
                var pl = BracketPlayer.Match(ent);
                if (pl.Success && _readingChoice.PlayerId == 0) _readingChoice.PlayerId = int.Parse(pl.Groups[1].Value);
                return;
            }
            if ((x = ChosenHead.Match(line)).Success)
            {
                var id = int.Parse(x.Groups[1].Value);
                _readingChosen = Choices.LastOrDefault(c => c.Id == id);
                if (_readingChosen != null) { _readingChosen.Resolved = true; _readingChosen.Chosen.Clear(); }
                _readingChoice = null;
                Changed?.Invoke();
                return;
            }
            if (_readingChosen != null && (x = ChosenEntity.Match(line)).Success)
            {
                _readingChosen.Chosen.Add(ResolveId(x.Groups[1].Value));
                return;
            }
            if (OptionsHead.IsMatch(line))
            {
                _optionsFresh = true;
                _readingChoice = null;
                return;
            }
            if ((x = OptionLine.Match(line)).Success)
            {
                if (_optionsFresh) { Playable.Clear(); UsableNow.Clear(); _optionsFresh = false; }
                if (x.Groups[1].Value != "POWER" || x.Groups[3].Value != "NONE") return;
                var id = ResolveId(x.Groups[2].Value);
                if (id == 0 || !Entities.TryGetValue(id, out var e) || e.Controller != FriendlyPlayerId) return;
                UsableNow.Add(id);
                if (e.Zone == "HAND") Playable.Add(id);
                Changed?.Invoke();
            }
        }

        // ================================================================== blocks and secrets

        private void OnBlockStart(string type, int source, int target)
        {
            // A new top-level action by a player: everything the previous action set off has resolved. (Top-level
            // TRIGGER/DEATHS blocks are follow-ups of the previous action, so they don't count.)
            if (_blocks.Count == 0 && (type == "PLAY" || type == "ATTACK"))
            {
                ResolvePendingChecks();
                foreach (var c in Choices) c.Resolved = true;
            }
            _blocks.Add(new Block { Type = type, Source = source, Target = target });

            if (source == 0 || !Entities.TryGetValue(source, out var e)) return;
            var friendly = FriendlyPlayerId != 0 && e.Controller == FriendlyPlayerId;

            if (type == "PLAY")
            {
                if (e.CardType == "HERO_POWER")
                {
                    if (friendly) FriendlyHeroPowerUses++;
                    Emit(GameEventKind.Play, friendly, e.CardId, $"{(friendly ? "You" : "Opponent")} used {CardName(e)} (hero power)");
                    return;
                }
                e.PlayedTurn = Turn;
                if (friendly) _friendlyPlays.Add((Turn, e.Id));
                else _opponentPlays.Add((Turn, e.Id, !e.StartedInDeck));
                if (e.CardType == "SPELL") { if (friendly) FriendlySpellsCast++; else OpponentSpellsCast++; }
                if (!friendly && _oppTurn != null) { _oppTurn.CardsPlayed++; _oppTurn.CostsPlayed.Add(e.Int("COST")); }
                Playable.Remove(e.Id);
                UsableNow.Remove(e.Id);
                Emit(GameEventKind.Play, friendly, e.KnownCardId, $"{(friendly ? "You" : "Opponent")} played {CardName(e)}");

                if (friendly && IsFriendlyTurn)
                {
                    FriendlyCardsPlayedThisTurn++;
                    var triggers = new List<SecretTrigger>();
                    if (e.CardType == "SPELL") triggers.Add(SecretTrigger.SpellCast);
                    if (e.CardType == "MINION") triggers.Add(SecretTrigger.MinionPlayed);
                    if (FriendlyCardsPlayedThisTurn == 3) triggers.Add(SecretTrigger.ThirdCardPlayed);
                    if (triggers.Count > 0) QueueCheck(triggers);
                }
            }
            else if (type == "ATTACK" && friendly && IsFriendlyTurn)
            {
                var triggers = new List<SecretTrigger>();
                if (e.IsMinion) triggers.Add(SecretTrigger.MinionAttacks);
                if (target != 0 && Entities.TryGetValue(target, out var t) && t.Controller == OpponentPlayerId)
                {
                    if (t.CardType == "HERO") triggers.Add(SecretTrigger.HeroAttacked);
                    else if (t.IsMinion) triggers.Add(SecretTrigger.TheirMinionAttacked);
                }
                if (triggers.Count > 0) QueueCheck(triggers);
            }
        }

        private void AddOpponentSecret(Entity e)
        {
            var heroClass = HeroClass(OpponentPlayerId);
            var state = new SecretState { EntityId = e.Id, PlayedTurn = Turn };
            var creator = e.Int("CREATOR");
            if (creator != 0) state.CreatedBy = EntityCardId(creator);

            var cls = e.Tag("CLASS") ?? heroClass;   // a secret keeps its own class even if generated
            var classSecrets = Secrets.ForClass(ClassName(cls) ?? heroClass).Select(s => s.CardId).ToList();
            // You can't have two copies of the same secret active at once.
            var active = Entities.Values.Where(x => x.Controller == OpponentPlayerId && x.Zone == "SECRET" && !string.IsNullOrEmpty(x.CardId)).Select(x => x.CardId);
            foreach (var id in classSecrets.Except(active)) state.Candidates.Add(id);
            OpponentSecrets[e.Id] = state;

            var names = string.Join(", ", state.Candidates.Select(_cards.NameOf));
            Emit(GameEventKind.Secret, false, null,
                $"Opponent played a secret{(state.CreatedBy != null ? $" (created by {_cards.NameOf(state.CreatedBy)})" : "")}: could be {(names.Length > 0 ? names : "anything")}");
        }

        /// <summary>CLASS tag values are numeric in some logs; map the common ones.</summary>
        private static string ClassName(string cls)
        {
            if (string.IsNullOrEmpty(cls)) return null;
            switch (cls)
            {
                case "3": return "HUNTER";
                case "4": return "MAGE";
                case "5": return "PALADIN";
                case "7": return "ROGUE";
                default: return int.TryParse(cls, out _) ? null : cls;
            }
        }

        private void RevealSecret(Entity e)
        {
            if (!OpponentSecrets.Remove(e.Id)) return;
            foreach (var c in _pendingChecks) c.RevealedDuring = true;
            var id = e.KnownCardId;
            if (!string.IsNullOrEmpty(id))
            {
                RevealedSecrets.Add(id);
                Emit(GameEventKind.Secret, false, id, $"Opponent's secret was {_cards.NameOf(id)}");
            }
        }

        private void QueueCheck(IEnumerable<SecretTrigger> triggers)
        {
            if (OpponentSecrets.Count == 0) return;
            var check = new SecretCheck
            {
                Secrets = OpponentSecrets.Keys.ToList(),
                TheyHadBoardSpace = Minions(OpponentPlayerId).Count < 7,
                YouHadMinion = Minions(FriendlyPlayerId).Count > 0,
            };
            foreach (var t in triggers) check.Triggers.Add(t);
            // "After you cast a spell, destroy one of your minions": judge it on the board after the spell resolved.
            check.CheckYouHaveMinionAtResolve = check.Triggers.Contains(SecretTrigger.SpellCast);
            _pendingChecks.Add(check);
        }

        private void QueueYourTurnEnds() => QueueCheck(new[] { SecretTrigger.YourTurnEnds });

        /// <summary>
        /// For each action that would have set off a secret, if no secret was revealed while it resolved, the hidden
        /// secrets can't be any secret with that trigger (provided its condition held).
        /// </summary>
        private void ResolvePendingChecks()
        {
            if (_pendingChecks.Count == 0) return;
            var checks = _pendingChecks.ToList();
            _pendingChecks.Clear();
            var youHaveMinionNow = Minions(FriendlyPlayerId).Count > 0;

            foreach (var c in checks)
            {
                if (c.RevealedDuring) continue;   // something triggered: don't guess which
                foreach (var sid in c.Secrets)
                {
                    if (!OpponentSecrets.TryGetValue(sid, out var state)) continue;
                    foreach (var cand in state.Candidates.ToList())
                    {
                        var rule = Secrets.ById(cand);
                        if (rule == null || !c.Triggers.Contains(rule.Trigger)) continue;
                        if (rule.Condition == SecretCondition.TheyNeedBoardSpace && !c.TheyHadBoardSpace) continue;
                        if (rule.Condition == SecretCondition.YouNeedAMinion)
                        {
                            var had = c.CheckYouHaveMinionAtResolve ? youHaveMinionNow : c.YouHadMinion;
                            if (!had) continue;
                        }
                        state.Candidates.Remove(cand);
                    }
                }
            }
            Changed?.Invoke();
        }

        // ================================================================== helpers

        private int ResolveId(string entityRef)
        {
            entityRef = entityRef.Trim();
            if (int.TryParse(entityRef, out var n)) return n;
            var m = BracketId.Match(entityRef);
            if (m.Success) return int.Parse(m.Groups[1].Value);
            if (entityRef == "GameEntity") return _gameEntityId;
            // A player name
            var pid = ResolvePlayerByName(entityRef);
            return pid != 0 && _playerIdToEntity.TryGetValue(pid, out var eid) ? eid : 0;
        }

        private Entity GetOrCreate(int id)
        {
            if (!Entities.TryGetValue(id, out var e)) Entities[id] = e = new Entity { Id = id, ZoneTurn = Turn };
            return e;
        }

        private string NameOf(int playerId) => PlayerNames.TryGetValue(playerId, out var n) ? n : $"player {playerId}";

        private void Emit(GameEventKind kind, bool friendly, string cardId, string text)
        {
            if (Quiet) return;
            _emit?.Invoke(new GameEvent { Kind = kind, Friendly = friendly, CardId = cardId, Text = text });
        }
    }
}
